const languageButtons=document.querySelectorAll('[data-language]');
const translatableElements=document.querySelectorAll('[data-i18n]');
const toast=document.querySelector('#toast');
const heroVideo=document.querySelector('.hero-video');
const videoToggle=document.querySelector('.video-toggle');
const howVisual=document.querySelector('[data-how-visual]');
const howCount=document.querySelector('[data-how-count]');
const howChapters=document.querySelectorAll('[data-how-step]');
const finalCta=document.querySelector('.final-cta');
const heroMedia=document.querySelector('.hero-media');
const energyFloats=document.querySelectorAll('.energy-float');
const journeyTabs=document.querySelectorAll('[data-journey]');
const journeyPanels=document.querySelectorAll('[data-journey-panel]');
const activityTabs=document.querySelectorAll('[data-activity]');
const activityStage=document.querySelector('[data-activity-stage]');
const activityRecord=document.querySelector('[data-activity-record]');
const activityExp=document.querySelector('[data-activity-exp]');
const activityBubble=document.querySelector('[data-activity-bubble]');
const activityIcon=document.querySelector('[data-activity-icon]');
const activityDeviceRecord=document.querySelector('[data-activity-device-record]');
const activityDeviceExp=document.querySelector('[data-activity-device-exp]');
let currentLanguage=localStorage.getItem('pixopet-language')||'en';
let toastTimer;
function applyLanguage(language){
  const copy=translations[language]||translations.en;
  currentLanguage=language;
  document.documentElement.lang=language==='zh'?'zh-CN':'en';
  document.title=copy.title;
  document.querySelector('meta[name="description"]').setAttribute('content',copy.description);
  translatableElements.forEach(element=>{const value=copy[element.dataset.i18n];if(typeof value==='string')element.innerHTML=value});
  document.querySelectorAll('[data-alt-en]').forEach(image=>{image.alt=image.dataset[language==='zh'?'altZh':'altEn']});
  languageButtons.forEach(button=>{const active=button.dataset.language===language;button.classList.toggle('is-active',active);button.setAttribute('aria-pressed',String(active))});
  localStorage.setItem('pixopet-language',language);
}
function showDownloadMessage(){toast.textContent=translations[currentLanguage].toast;toast.classList.add('is-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('is-visible'),2600)}
function updateVideoToggle(){const paused=heroVideo.paused;videoToggle.setAttribute('aria-pressed',String(paused));videoToggle.setAttribute('aria-label',paused?'Play background video':'Pause background video');videoToggle.querySelector('span').textContent=paused?'▶':'Ⅱ'}
function setHowStep(step){
  if(!howVisual)return;
  const index={sleep:'01',focus:'02',move:'03'}[step]||'01';
  howVisual.dataset.step=step;
  howCount.textContent=index;
  howChapters.forEach(chapter=>chapter.classList.toggle('is-active',chapter.dataset.howStep===step));
}
function setJourneyStep(step){
  journeyTabs.forEach(tab=>{const active=tab.dataset.journey===step;tab.classList.toggle('is-active',active);tab.setAttribute('aria-selected',String(active))});
  journeyPanels.forEach(panel=>panel.classList.toggle('is-active',panel.dataset.journeyPanel===step));
}
const activityData={
  sleep:{record:'7h 42m',exp:'+78 EXP',bubble:'+26',icon:'assets/sleep@3x.png'},
  focus:{record:'2h 15m',exp:'+54 EXP',bubble:'+18',icon:'assets/focus@3x.png'},
  move:{record:'3,775',exp:'+380 EXP',bubble:'+127',icon:'assets/move@3x.png'}
};
function setActivityStep(step){
  if(!activityStage||!activityData[step])return;
  const data=activityData[step];
  activityTabs.forEach(tab=>{const active=tab.dataset.activity===step;tab.classList.toggle('is-active',active);tab.setAttribute('aria-selected',String(active))});
  activityStage.dataset.activityStage=step;
  activityStage.classList.remove('is-changing');void activityStage.offsetWidth;activityStage.classList.add('is-changing');
  activityRecord.textContent=data.record;activityExp.textContent=data.exp;activityBubble.textContent=data.bubble;activityIcon.src=data.icon;activityDeviceRecord.textContent=data.record;activityDeviceExp.textContent=data.exp;
}
languageButtons.forEach(button=>button.addEventListener('click',()=>applyLanguage(button.dataset.language)));
journeyTabs.forEach(tab=>tab.addEventListener('click',()=>setJourneyStep(tab.dataset.journey)));
activityTabs.forEach(tab=>tab.addEventListener('click',()=>setActivityStep(tab.dataset.activity)));
document.querySelectorAll('[data-download]').forEach(button=>button.addEventListener('click',showDownloadMessage));
videoToggle.addEventListener('click',()=>{if(heroVideo.paused)heroVideo.play();else heroVideo.pause();updateVideoToggle()});
heroVideo.addEventListener('play',updateVideoToggle);heroVideo.addEventListener('pause',updateVideoToggle);
let howScrollFrame;
function updateHowFromScroll(){
  cancelAnimationFrame(howScrollFrame);
  howScrollFrame=requestAnimationFrame(()=>{
    if(!howChapters.length)return;
    const targetY=window.innerHeight*.52;
    let closest=howChapters[0];
    let distance=Infinity;
    howChapters.forEach(chapter=>{
      const rect=chapter.getBoundingClientRect();
      const nextDistance=Math.abs(rect.top+rect.height*.5-targetY);
      if(nextDistance<distance){distance=nextDistance;closest=chapter}
    });
    setHowStep(closest.dataset.howStep);
  });
}
window.addEventListener('scroll',updateHowFromScroll,{passive:true});
window.addEventListener('resize',updateHowFromScroll);
const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-in-view');revealObserver.unobserve(entry.target)}}),{threshold:.16});
document.querySelectorAll('[data-reveal]').forEach(element=>revealObserver.observe(element));
let heroMotionFrame;
function updateHeroMotion(){
  cancelAnimationFrame(heroMotionFrame);
  heroMotionFrame=requestAnimationFrame(()=>{
    if(!heroMedia)return;
    const progress=Math.min(1,Math.max(0,window.scrollY/(window.innerHeight*.9)));
    heroMedia.style.setProperty('--hero-y',`${70-progress*54}px`);
    heroMedia.style.setProperty('--hero-scale',String(.9+progress*.1));
    energyFloats.forEach((card,index)=>card.style.setProperty('--float-y',`${progress*[-72,-118,-92][index]}px`));
  });
}
window.addEventListener('scroll',updateHeroMotion,{passive:true});
window.addEventListener('resize',updateHeroMotion);
if(finalCta&&window.matchMedia('(pointer: fine)').matches&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){
  let pointerFrame;
  finalCta.addEventListener('pointermove',event=>{
    cancelAnimationFrame(pointerFrame);
    pointerFrame=requestAnimationFrame(()=>{
      const rect=finalCta.getBoundingClientRect();
      const x=Math.min(1,Math.max(0,(event.clientX-rect.left)/rect.width));
      const y=Math.min(1,Math.max(0,(event.clientY-rect.top)/rect.height));
      finalCta.classList.add('is-tracking');
      finalCta.style.setProperty('--mouse-x',`${(x*100).toFixed(1)}%`);
      finalCta.style.setProperty('--mouse-y',`${(y*100).toFixed(1)}%`);
      finalCta.style.setProperty('--shift-x',`${((x-.5)*18).toFixed(1)}px`);
      finalCta.style.setProperty('--shift-y',`${((y-.5)*14).toFixed(1)}px`);
      finalCta.style.setProperty('--tilt',`${((x-.5)*3).toFixed(2)}deg`);
    });
  });
  finalCta.addEventListener('pointerleave',()=>{
    finalCta.classList.remove('is-tracking');
    finalCta.style.setProperty('--mouse-x','50%');
    finalCta.style.setProperty('--mouse-y','38%');
    finalCta.style.setProperty('--shift-x','0px');
    finalCta.style.setProperty('--shift-y','0px');
    finalCta.style.setProperty('--tilt','0deg');
  });
}
if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){heroVideo.removeAttribute('autoplay');heroVideo.pause()}
applyLanguage(currentLanguage);updateVideoToggle();updateHowFromScroll();updateHeroMotion();
